Translate("ruRU", "deadwind-pass", {
	title = "Перевал Мертвого Ветра",
	aliases = { "Мертвый Ветер" },
	sections = {
		{
			title = "Обзор",
			text = [=[Перевал Мертвого Ветра — бесплодная расселина в горах между {link:duskwood}Сумеречным лесом{/link} и {link:swamp-of-sorrows}Болотом Печали{/link}. Холодный ветер стонет в ней без отдыха, и он дал перевалу имя. Здесь ничто не растет как следует. Деревья стоят серые и голые, трава редка и бесцветна, а небо над головой, кажется, всегда цвета пепла. На юге перевала, в глубокой котловине изломанной земли, поднимается башня {link:karazhan}Каражан{/link}. Она была домом последнего Хранителя, {link:medivh}Медива{/link}, и местом, где он умер. Путники, которым приходится пересекать Мертвый Ветер, держатся дороги, говорят мало и не смотрят слишком долго в сторону башни.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, кто первым дал перевалу имя и был ли он когда-нибудь зеленым. Несомненно одно: большой мир узнал о нем из-за башни в его сердце. {link:medivh}Медив{/link} поселился в {link:karazhan}Каражан{/link}е в годы перед {link:first-war}Первой войной{/link} и оттуда вел долгие замыслы, которые привели {link:orcs}орк{/link}ов {red:draenor}Дренора{/red} в {link:azeroth}Азерот{/link}. Перевал лежал на юго-восточном краю старого королевства {link:kingdom-of-stormwind}Азерот{/link}, и мало у кого из жителей королевства была причина туда ходить. Хранитель был другом короля, и его башню оставили в покое.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:medivh}Медив{/link} давно мертв, и его башня стоит темная и запертая. Теперь перевал не принадлежит ни одному королевству. {link:kingdom-of-stormwind}Штормград{/link} не посылает дозоров так далеко на восток, и у {link:horde}Орды{/link} здесь тоже нет заставы. Неупокоенные духи блуждают среди руин у подножия {link:karazhan}Каражан{/link}а, а бледные неживые создания ухаживают за могилами Надела {link:morgan-stern}Морган{/link}а позади башни. {link:ogres}Огры{/link} устроили свои холмы вдоль южной дороги, в узкой долине, которую зовут {link:the-vice}Погань{/link}ю. Над оврагами кружат огромные птицы-падальщики. По самой дороге купцы и солдаты, идущие в {link:swamp-of-sorrows}Болото Печали{/link} и в {link:blasted-lands}Выжженные земли{/link}, спешат пройти засветло. В Сумеречном лесу жители Темнолесья говорят, что {link:dark-riders}темные всадники{/link}, вырезавшие семью Йоргена, спустились с этого перевала и что никто не знает, куда они уходят, когда возвращаются.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}Неупокоенные мертвецы.{/b} Тени, стенающие призраки и проклятые души обитают в разрушенных домах перед {link:karazhan}Каражан{/link}ом. Чьи это духи, ни один живой свидетель сказать не может.
• {b}Неживые Надела {link:morgan-stern}Морган{/link}а.{/b} Бледные смотрители и жильцы хранят часовню и кладбище позади башни.
• {b}Огры Мертвого Ветра.{/b} {link:deadwind-ogres}Огры Мертвого Ветра{/link} держат холмы Погани и {link:grosh-gok-compound}Поселок Грош'гок{/link}; среди них есть чернокнижники и {link:ogres}огр{/link}ы-маги.
• {b}Птицы-падальщики.{/b} Стервятники, которых зовут небесными тенями, кружат над северными оврагами и открытыми местами перевала.
• {b}{link:dark-riders}Темные всадники{/link}.{/b} Днем их здесь не видят. Но уцелевшие в Сумеречном лесу называют Мертвый Ветер местом, откуда они выезжают.]=],
		},
		{
			title = "История",
			text = [=[• {b}Башня Хранителя.{/b} {link:medivh}Медив{/link} поселился в {link:karazhan}Каражан{/link}е после того, как очнулся от долгого сна своей юности. Там он занимался науками, собрал большую библиотеку и принимал мало гостей.
• {b}Открытие Портала.{/b} Из башни Медив дотянулся через пустоту до Дренора и до чернокнижника {link:gul-dan}Гул'дана{/link}. Вместе они открыли {link:dark-portal}Темный портал{/link} в Черных топях, далеко на юге.
• {b}Ученик и посланница.{/b} {link:kirin-tor}Кирин-Тор{/link} из {link:dalaran}Даларана{/link} послал молодого мага {link:khadgar}Кадгара{/link} в ученики к Хранителю. Полуорчиха {link:garona}Гарона{/link} пришла в башню посланницей Орды. Вдвоем они узнали правду о предательстве Хранителя.
• {b}Смерть Хранителя.{/b} Сэр {link:anduin-lothar}Андуин Лотар{/link} и Кадгар поднялись в Каражан и встали против его хозяина. Там Хранитель был убит. Гул'дан, который в тот миг проник в разум умирающего, впал в долгое оцепенение.
• {b}Безмолвие.{/b} С того дня башня темна. {link:first-war}Первая война{/link} и {link:second-war}Вторая война{/link} прошли мимо нее, а перевал вокруг стал местом, которое живые обходят стороной.]=],
		},
		{
			title = "Предания перевала",
			text = [=[• Дорога, что идет из Сумеречного леса к Болоту Печали, — единственный безопасный путь через перевал. Вдоль нее стоят старые предостережения, и одно из них говорит просто: «Поверните назад!»
• У перекрестка стоит мертвое дерево, и на его ветвях до сих пор качаются повешенные. Никто в Сумеречном лесу не берется сказать, кто их повесил.
• {link:ogres}Огры{/link} Погани держат в своих лагерях горящие костры и большие котлы. Что они надеются найти в такой мертвой земле, никто у них не спрашивал.
• За башней есть маленькая часовня и кладбище. Какая бы паства ни собиралась там когда-то, ее мертвые не знают покоя.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, отчего земля перевала так бесплодна и была ли она такой до того, как пришел {link:medivh}Медив{/link}. Ни один рассказ не сообщает и того, кто жил в разрушенных домах под {link:karazhan}Каражан{/link}ом и что с ними сталось. Эта запись хранит то, что видят путники, и то, что утверждают истории о Хранителе.]=],
		},
	},
	mentions = {
		{
			text = [=[«Месть {link:sven-yorgen}Свен{/link}а», где впервые названы {link:dark-riders}темные всадники{/link} Мертвого Ветра]=],
		},
	},
})

Translate("ruRU", "karazhan", {
	title = "Каражан",
	aliases = { "башня Каражан", "башня Медива" },
	sections = {
		{
			title = "Обзор",
			text = [=[Каражан — башня последнего Хранителя, {link:medivh}Медива{/link}. Она поднимается из глубокой котловины на юге {link:deadwind-pass}Перевала Мертвого Ветра{/link} — высокий шпиль темного камня над россыпью разрушенных домов. Многие годы она была обителью одного из могущественнейших магов, каких знал мир. Она же — место, откуда была приведена в движение {link:first-war}Первая война{/link}, и место, где умер тот, кто ее начал. Теперь ее двери закрыты. Ни один слуга не отзывается у ворот, и огня для гостей здесь не зажигают.]=],
		},
		{
			title = "Дом Хранителя",
			text = [=[{link:medivh}Медив{/link} пришел в Каражан взрослым человеком, после долгого сна своей юности в {link:northshire-abbey}Аббатстве Североземья{/link}. Он жил там лишь с небольшим числом слуг, которых возглавлял престарелый кастелян. В башне была большая библиотека, комнаты со странными приборами и обсерватория, открытая звездам. Те, кто жил в ее стенах, замечали, что она не всегда держится настоящего. {link:khadgar}Кадгар{/link} в бытность учеником видел, как в ее залах возникают и тают сцены из других дней: одни давно минули, другие еще не наступили. Маги {link:kirin-tor}Кирин-Тора{/link} давно желали узнать тайны башни. Никого из них туда не звали, пока Хранитель наконец не согласился взять ученика.]=],
		},
		{
			title = "Предательство",
			text = [=[В этих стенах {link:medivh}Медив{/link} дотянулся через пустоту до умирающего {red:draenor}Дренора{/red}. Он нашел чернокнижника {link:gul-dan}Гул'дана{/link} и {link:orcs}орк{/link}ов, которые тому служили, и вместе они открыли {link:dark-portal}Темный портал{/link}. Годами друзья Хранителя в {link:stormwind-city}Штормград{/link}е ничего об этом не знали. Правду вынесли из башни два неожиданных союзника: {link:khadgar}Кадгар{/link}, ученик, присланный из {link:dalaran}Даларана{/link}, и {link:garona}Гарона{/link}, полуорчиха, посланница {link:horde}Орды{/link}. То, что они узнали в Каражане, они принесли королю {link:llane-wrynn}Ллейну Ринну{/link}.]=],
		},
		{
			title = "Последняя битва",
			text = [=[Сэр {link:anduin-lothar}Андуин Лотар{/link} и {link:khadgar}Кадгар{/link} вернулись в Каражан, чтобы покончить с войной у ее корня, и {link:garona}Гарона{/link} была с ними. Они сразились с Хранителем в его собственной башне, и {link:medivh}Медив{/link} был убит. В тот самый миг {link:gul-dan}Гул'дан{/link} обшаривал разум Хранителя в поисках тайн гробницы, где лежит {link:sargeras}Саргерас{/link}. Когда Медив умер, чернокнижника бросило в оцепенение, от которого он долго не мог очнуться. Кадгар спустился из башни постаревшим намного больше своих лет. Каражан остался позади него пустым.]=],
		},
		{
			title = "В эти дни",
			text = [=[Башня запечатана. Духи, что блуждают среди разрушенных домов у ее подножия, — единственное ее общество. Однако знание, которым владел {link:medivh}Медив{/link}, исчезло не целиком. Сочинения последнего ученика башни, {link:khadgar}Кадгар{/link}а, до сих пор переписывают и изучают ученые {link:stormwind-city}Штормграда{/link}, и {link:the-night-watch}дозорные{/link}, что стерегут {link:dark-portal}Темный портал{/link} из {link:nethergarde-keep}Крепости Стражей Пустоты{/link}, разыскивают их.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, кто воздвиг Каражан, когда он был построен и почему стоит в столь пустынном месте. Что лежит за его запечатанными дверями в эти дни, не записал ни один живой свидетель.]=],
		},
	},
	chapters = {
		{
			title = "Сочинения ученика",
			hint = [=[Верните утраченное сочинение ученого и отнесите его дозорным, которые стерегут Темный портал.]=],
			text = [=[Гонец штормградской академии отправился в {link:nethergarde-keep}Крепость Стражей Пустоты{/link} с драгоценным текстом: сочинениями о схождении миров, которые написал {link:khadgar}Кадгар{/link}. Он потерял их в Болоте Печали — их отняли болотные твари. Когда они наконец дошли до крепости, дозорный, который о них просил, едва мог дождаться, чтобы приняться за чтение. Человек, некогда учившийся рядом с Хранителем, понял лучше всех живущих, как были соединены два мира. Те, кто ныне несет стражу над Порталом, тоже хотели это понять.]=],
		},
	},
	mentions = {
		{ text = "«Просьба Мазена», зов о помощи из библиотеки академии" },
		{
			text = [=[«Просьба Мазена», сочинения мага {link:khadgar}Кадгар{/link}а доставлены в {link:nethergarde-keep}Крепость Стражей Пустоты{/link}]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Медив", note = "ее хозяин" },
		{ id = "khadgar", name = "Кадгар", note = "ее последний ученик" },
		{ id = "garona", name = "Гарона", note = "пришла посланницей Орды" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "убил здесь Хранителя" },
		{ id = "aegwynn", name = "Эгвин", note = "мать Хранителя" },
	},
})

Translate("ruRU", "morgan-s-plot", {
	title = "Надел Моргана",
	sections = {
		{
			title = "Обзор",
			text = [=[Надел Моргана — маленькая часовня и кладбище прямо за {link:karazhan}Каражаном{/link}. Его камни покосились, а кровли наполовину нет. Возможно, когда-то он служил деревне, стоявшей у подножия башни, но никто уже не помнит, кого там хоронили и кем был тот {link:morgan-stern}Морган{/link}, чье имя он носит. Могилы не оставлены в покое. Бледные фигуры — неживые смотрители и жильцы этого места — ходят между часовней и склоном холма, словно у них все еще есть обязанности. Гостям они не рады.]=],
		},
	},
})

Translate("ruRU", "deadman-s-crossing", {
	title = "Перекресток Мертвеца",
	sections = {
		{
			title = "Обзор",
			text = [=[Перекресток Мертвеца — место, где расходится дорога через {link:deadwind-pass}Перевал Мертвого Ветра{/link}. Один путь ведет на запад, в {link:duskwood}Сумеречный лес{/link}, другой — на восток, к {link:swamp-of-sorrows}Болоту Печали{/link}, третий — на юг, вниз, к котловине, где стоит {link:karazhan}Каражан{/link}. У перекрестка стоит мертвое дерево, и на его ветвях висят тела повешенных. Дорожный столб дает путникам прямой совет повернуть назад. Большинство следует ему по-своему: они не сходят с дороги и не сворачивают на юг.]=],
		},
	},
})

Translate("ruRU", "ariden-s-camp", {
	title = "Лагерь Аридена",
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Аридена — покинутая стоянка чуть севернее дороги, что идет через {link:deadwind-pass}Перевал Мертвого Ветра{/link}. Холодное кострище и немного брошенных вещей — вот все, что осталось. Кем бы ни был Ариден — мужчиной или женщиной, — этот путник покинул лагерь в спешке или не покинул его вовсе. Мало кто из путников здесь останавливается. В земле, где ходят мертвые, а {link:ogres}огр{/link}ы следят за дорогой, одинокий костер — приглашение, на которое решаются немногие.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись этих дней не говорит, кем был Ариден, что привело этого путника на {link:deadwind-pass}Мертвый Ветер{/link} и что с ним сталось.]=],
		},
	},
})

Translate("ruRU", "the-vice", {
	title = "Погань",
	sections = {
		{
			title = "Обзор",
			text = [=[Погань — узкая долина на юго-востоке {link:deadwind-pass}Перевала Мертвого Ветра{/link}, где крутые каменные стены стискивают дорогу на {link:karazhan}Каражан{/link}. {link:deadwind-ogres}Огры Мертвого Ветра{/link} вырыли в этих стенах свои холмы. Из пещер они следят за дорогой внизу, а их костры и котлы дымят среди камней. Громилы и молотобойцы охраняют лагеря, а чернокнижники и {link:ogres}огр{/link}ы-маги держатся у огней. Никто не знает, почему огры выбрали для жилья столь мертвое место.]=],
		},
	},
})

Translate("ruRU", "grosh-gok-compound", {
	title = "Поселок Грош'гок",
	aliases = { "Грош'гок" },
	sections = {
		{
			title = "Обзор",
			text = [=[Поселок Грош'гок — самый большой из {link:ogres}огр{/link}ских холмов Погани и самый южный. Его пещеры уходят глубоко в утесы над дорогой на {link:karazhan}Каражан{/link}. Это главное логово {link:deadwind-ogres}огров Мертвого Ветра{/link}, и чернокнижники клана держатся рядом с ним. Путникам, которые сходят с дороги возле поселка, редко выпадает случай сойти с нее еще раз.]=],
		},
	},
})

Translate("ruRU", "sleeping-gorge", {
	title = "Спящая теснина",
	sections = {
		{
			title = "Обзор",
			text = [=[Спящая теснина — небольшая расселина на востоке {link:deadwind-pass}Перевала Мертвого Ветра{/link}. Одна из троп, ведущих на юг, к {link:karazhan}Каражану{/link}, некоторое время идет по ее дну, а потом сворачивает на восток, в {link:the-vice}Погань{/link}. Кто бы ни дал ей имя, теснина — не место для отдыха. Путники, которые идут через нее, ступают тихо, ибо сразу за ней лежат {link:ogres}огр{/link}ы Погани.]=],
		},
	},
})

Translate("ruRU", "deadwind-ravine", {
	title = "Овраг Мертвого Ветра",
	sections = {
		{
			title = "Обзор",
			text = [=[Овраг Мертвого Ветра — широкая выемка, по которой дорога поднимается из {link:duskwood}Сумеречного леса{/link} на {link:deadwind-pass}Перевал Мертвого Ветра{/link}. Здесь темные леса наконец уступают место серому камню и мертвым деревьям. Ветер, давший перевалу имя, сильнее всего дует в овраге, и {link:ogres}огр{/link}омные птицы-падальщики, которых зовут небесными тенями, парят на нем в вышине, высматривая все, что падает. Для тех, кто идет из Темнолесья, овраг — первый взгляд на землю, еще более унылую, чем их собственная.]=],
		},
	},
})

Translate("ruRU", "deadwind-ogres", {
	title = "Огры Мертвого Ветра",
	aliases = { "огры Перевала Мертвого Ветра", "огры перевала" },
	sections = {
		{
			title = "Обзор",
			text = [=[Огры Мертвого Ветра — {link:ogres}огры{/link}, которые поселились на юге {link:deadwind-pass}Перевала Мертвого Ветра{/link}. Они живут в холмах, вырытых в утесах Погани, и величайший из них — {link:grosh-gok-compound}Поселок Грош'гок{/link}. Ни одна летопись не говорит, откуда они пришли, когда и что привлекло их в землю, где почти ничто не живет.]=],
		},
		{
			title = "Их обычаи",
			text = [=[В клане есть громилы и молотобойцы, которые охраняют его лагеря и дорогу под ними. Есть в нем и чернокнижники, и {link:ogres}огр{/link}ы-маги, которые смотрят за огнями и котлами холмов. То, что клан числит среди своих чернокнижников, — мрачный знак. Темные искусства пришли к ограм {link:azeroth}Азерот{/link}а вместе с {link:horde}Ордой{/link}, и никто не знает, у кого им научились эти огры.]=],
		},
		{
			title = "В наши дни",
			text = [=[{link:ogres}Огры{/link} нападают из засады на всякого, кто сойдет с дороги в сторону {link:karazhan}Каражана{/link}. Саму башню они, насколько известно, не тревожат, и башня не тревожит их. Ни одно королевство не посылало против них солдат. {link:deadwind-pass}Мертвый Ветер{/link} лежит слишком далеко от любого владыки, которому было бы до этого дело.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Почему {link:ogres}огр{/link}ы выбрали {link:the-vice}Погань{/link} и чего они хотят от такой мертвой страны, нигде не записано. Не записано и имя их вождя.]=],
		},
	},
})

Translate("ruRU", "dark-riders", {
	title = "Темные всадники",
	aliases = { "темные всадники", "темный всадник" },
	sections = {
		{
			title = "Обзор",
			text = [=[Темные всадники — отряд конных, которые выезжают с {link:deadwind-pass}Перевала Мертвого Ветра{/link} и совершают набеги на юг {link:duskwood}Сумеречного леса{/link}. Они ездят в черном и нападают без предупреждения. Больше о них почти ничего не известно. У них нет известного знамени, они не говорят ни с кем из тех, кто остается в живых после встречи с ними, и возвращаются на перевал, когда дело сделано.]=],
		},
		{
			title = "Их деяния",
			text = [=[Это темные всадники напали на ферму, которой владел {link:sven-yorgen}Свен Йорген{/link}, пока его не было дома, и убили его семью. Свен гнался за ними и потерял их след. Рудокоп, бежавший из шахты у Погибели Роланда, прятался в ту ночь в амбаре семьи Йоргена и видел резню. Позже его дневник рассказал остальное. Известно, что всадники бывают у некроманта {link:morbent-fel}Морбента Фела{/link} в {link:forlorn-rowe}Покинутой усадьбе{/link}, над Вороньим Холмом. Свен видел, как они говорили с ним там.]=],
		},
		{
			title = "В наши дни",
			text = [=[{link:morbent-fel}Морбент Фел{/link} может пасть, но всадники остаются на свободе. {link:sven-yorgen}Свен Йорген{/link} держит свой лагерь на западном краю Сумеречного леса и живет ради дня, когда сумеет их найти. Чего бы они ни искали и кому бы ни служили, к ответу их пока не призвали.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись этих дней не говорит, кто такие темные всадники, кто их ведет и где на Мертвом Ветре они разбивают лагерь. Неизвестно и то, какая сделка связывает их с некромантом Морбентом Фелом.]=],
		},
	},
	mentions = {
		{ text = "«Месть {link:sven-yorgen}Свен{/link}а»" },
		{ text = "«Лагерь {link:sven-yorgen}Свен{/link}а»" },
		{
			text = [=[«Возвращение к {link:sven-yorgen}Свен{/link}у», где всадников видят с некромантом Морбентом Фелом]=],
		},
		{ text = "«{link:morbent-fel}Морбент Фел{/link}»" },
	},
	bonds = {
		{ id = "morbent-fel", name = "Морбент Фел", note = "их союзник в Сумеречном лесу" },
		{ id = "sven-yorgen", name = "Свен Йорген", note = "поклялся отомстить им за семью" },
		{ id = "jitters", name = "Джиттерс", note = "был свидетелем резни на ферме семьи Йоргена" },
	},
})
